Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string convertMarkdownToHTML(const std::string& markdown) {
    std::stringstream htmlStream;
    std::string line;

    // Titres (h1 à h6)
    std::regex titleRegex("^#{1,6}\\s(.*)$");
    while (std::getline(std::stringstream(markdown), line)) {
        std::smatch match;
        if (std::regex_match(line, match, titleRegex)) {
            std::string title = match[1].str();
            htmlStream << "<h" << match.size() << ">" << title << "</h" << match.size() << ">\n";
        } else {
            htmlStream << line << "\n";
        }
    }

    // Gras et italique
    std::regex italicRegex("(\\*_\\w+\\*)|(_\\w+_)");
    std::regex boldRegex("(\\**\\w+\\**)|(__\\w+__)");
    std::regex boldItalicRegex("(\\*\\w+\\*\\_\\w+\\*)|(__\\w+\\_*\\w+__)");
    std::string htmlText = htmlStream.str();
    std::regex_replace(htmlText, italicRegex, "$1");
    std::regex_replace(htmlText, boldRegex, "$1");
    std::regex_replace(htmlText, boldItalicRegex, "$1");

    // Lien
    std::regex linkRegex("\\[\\[(.+?)\\]\\]\\((.+?)\\)");
    std::regex_replace(htmlText, linkRegex, "<a href=\"$2\">$1</a>");

    // Liste
    std::regex unorderedListRegex("^(\\s+)-\\s(.*)$");
    std::regex orderedListRegex("^(\\s+\\d+\\.)\\s(.*)$");
    while (std::regex_search(htmlText, std::regex("\\n(\\s+[*-]+\\s.*)"), std::regex::format_first_only)) {
        std::string listText = std::regex_replace(std::regex_replace(std::regex_replace(std::regex_replace(std::regex_replace(htmlText, unorderedListRegex, "<ul><li>$2</li></ul>"), orderedListRegex, "<ol><li>$2</li></ol>"), std::regex("\\n"), ""), std::regex("^\\s+"), "");
        htmlText = std::regex_replace(htmlText, std::regex("\\n(\\s+[*-]+\\s.*)"), listText);
    }

    return htmlText;
}

int main() {
    std::string markdown = "Hello **world**! This is a [link](https://example.com). \n\n # Title 1\n\n ## Subtitle 1\n\n - Item 1\n - Item 2\n\n 1. Item 3\n\n **Bold** and *italic* text.";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Cette fonction utilise la bibliothèque de régularité de C++ pour détecter les différents éléments de Markdown (titres, gras et italique, liens, liste) et les convertir en HTML correspondant. Elle prend en entrée une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant le texte correspondant au format HTML. 

